"""Record the user-approved link modes without claiming backend implementation."""
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
MARK = '<!-- participant-link-modes-2026-09-23 -->'
BASE = 'https://www.figma.com/design/1LeVoicxDT7Sl8TpMPs4hr/Dashboard?node-id='

def append(path, body):
    target = ROOT / path
    old = target.read_text(encoding='utf-8') if target.exists() else ''
    if MARK not in old:
        target.write_text(old.rstrip() + '\n\n' + MARK + '\n' + body.strip() + '\n', encoding='utf-8')

def replace(path, old, new):
    target = ROOT / path
    source = target.read_text(encoding='utf-8')
    if old in source:
        target.write_text(source.replace(old, new), encoding='utf-8')

